mapper.select:
SELECT tenant_id, idempotency_key, request_id, channel, seller_account_id,
       item_id, conversation_id, buyer_id, work_item_id, created_at, updated_at
FROM cs_sla_work_item_request
WHERE tenant_id = #{tenantId}
  AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE cs_sla_work_item_request
SET work_item_id = #{workItemId}, updated_at = #{now}
WHERE request_id = #{requestId}
  AND work_item_id IS NULL

